{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "flip",
  "supportive_card_ids": ["C269", "C276", "C246"],
  "contradictory_card_ids": ["C189", "C237", "C272", "C277", "C281"],
  "prediction_basis_card_ids": ["C269", "C276", "C189", "C237"],
  "claims": [
    {
      "claim": "C269: a cinnamohydroxamic acid HDAC inhibitor bearing a secondary amine (10p) showed low Caco-2 absorptive permeability (Papp A→B 0.97×10^-6 cm/s) and marked efflux (ER 10.8), attributed to the secondary amine; this is the closest analog to the query's secondary-amine cinnamohydroxamic acid scaffold and provides coherent measured gut-wall efflux evidence.",
      "card_ids": ["C269"]
    },
    {
      "claim": "C276: the hydroxamic acid DPC333 was a P-gp substrate with intestinal clearance of 0.2–0.35 L/h/kg and ~20% of an IV dose recovered in the lumen, showing that hydroxamic acids can undergo substantial gut-wall efflux/excretion.",
      "card_ids": ["C276"]
    },
    {
      "claim": "C246: another cinnamohydroxamic acid with a basic pyrrolidinoethyl amine showed significant efflux (ER 9.2), supporting the pattern that basic amines in this chemotype drive efflux.",
      "card_ids": ["C246"]
    },
    {
      "claim": "C189/C237: SB939, a tertiary-amine cinnamohydroxamic acid, had high solubility and high Caco-2 permeability (Papp ~7×10^-6 cm/s), but the query's secondary amine diverges from this high-permeability analog, limiting transfer of that positive result.",
      "card_ids": ["C189", "C237"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C269", "C276", "C246"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query or an exact analog.",
    "Caco-2 efflux/permeability is indirect; no matched oral vs IV AUC for the query scaffold.",
    "Intestinal metabolism of the specific cinnamohydroxamic acid in the query was not directly measured.",
    "Transfer from benzimidazole cinnamohydroxamic acids to the indole query is uncertain.",
    "Dose, formulation, and saturation of efflux are unknown."
  ],
  "decision_summary": "L5 introduces C269, a cinnamohydroxamic acid HDAC inhibitor with a secondary amine that shows low Caco-2 Papp (0.97×10^-6 cm/s) and high efflux (ER 10.8), directly relevant to the query's secondary-amine cinnamohydroxamic acid scaffold; C276 further shows hydroxamic acids can undergo significant gut-wall efflux/excretion. This coherent measured efflux evidence, combined with the query's very low neutral fraction (0.01), supports F < 20% and overturns the L4 high prediction based on the tertiary-amine SB939 analog."
}

